using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<ITicketModelService, TicketModelService>();

var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "TicketModel.zip");
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(filePath: modelPath, watchForChanges: true);

var app = builder.Build();

// Train model at startup so the model file exists before predictions
var modelService = app.Services.GetRequiredService<ITicketModelService>();
modelService.TrainAndEvaluate();

app.MapControllers();
app.Run();

