 using Microsoft.Extensions.ML;
 using Microsoft.ML;
 using Microsoft.ML.Data;
 using TicketClassifier.Models;

 namespace TicketClassifier.Services;

 public interface ITicketModelService
 {
     TrainingMetricsResponse TrainAndEvaluate();
     TicketClassificationResponse Predict(TicketRequest request);
 }

 public class TicketModelService : ITicketModelService
 {
     private readonly ILogger<TicketModelService> _logger;
     private readonly IWebHostEnvironment _env;
     private readonly PredictionEnginePool<TicketData, TicketPrediction> _predictionEnginePool;
     private string[] _categoryNames = [];

     public TicketModelService(
         ILogger<TicketModelService> logger,
         IWebHostEnvironment env,
         PredictionEnginePool<TicketData, TicketPrediction> predictionEnginePool)
     {
         _logger = logger;
         _env = env;
         _predictionEnginePool = predictionEnginePool;
     }

     private string GetDataPath() => Path.Combine(_env.ContentRootPath, "Data", "tickets.csv");
     private string GetModelPath() => Path.Combine(_env.ContentRootPath, "Data", "TicketModel.zip");

     public TrainingMetricsResponse TrainAndEvaluate()
     {
         var mlContext = new MLContext(seed: 42);

         var data = mlContext.Data.LoadFromTextFile<TicketData>(
             GetDataPath(), hasHeader: true, separatorChar: ',', allowQuoting: true);

         var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);

         var pipeline = mlContext.Transforms.Conversion
                 .MapValueToKey("Label", nameof(TicketData.Category))
             .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
             .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
             .Append(mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
             .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
             .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

         _logger.LogInformation("Training ticket classification model...");
         var model = pipeline.Fit(split.TrainSet);

         var predictions = model.Transform(split.TestSet);
         var metrics = mlContext.MulticlassClassification.Evaluate(predictions, "Label");

         _logger.LogInformation("Model evaluation metrics:");
         _logger.LogInformation("  MacroAccuracy:    {MacroAccuracy:F4}", metrics.MacroAccuracy);
         _logger.LogInformation("  MicroAccuracy:    {MicroAccuracy:F4}", metrics.MicroAccuracy);
         _logger.LogInformation("  LogLoss:          {LogLoss:F4}", metrics.LogLoss);
         _logger.LogInformation("  LogLossReduction: {LogLossReduction:F4}", metrics.LogLossReduction);

         // Extract category names from the label key mapping
         var labelBuffer = new VBuffer<ReadOnlyMemory<char>>();
         predictions.Schema["PredictedLabel"]
             .GetSlotNames(ref labelBuffer);

         // If slot names are empty, extract from the Score column key type
         var scoreColumn = predictions.Schema["Score"];
         if (scoreColumn.Type is VectorDataViewType vectorType &&
             vectorType.ItemType is KeyDataViewType)
         {
             scoreColumn.GetSlotNames(ref labelBuffer);
         }

         if (labelBuffer.Length > 0)
         {
             _categoryNames = labelBuffer.DenseValues()
                 .Select(v => v.ToString())
                 .ToArray();
         }
         else
         {
             // Fallback: extract unique categories from the training data
             _categoryNames = mlContext.Data.CreateEnumerable<TicketData>(split.TrainSet, reuseRowObject: false)
                 .Select(t => t.Category)
                 .Distinct()
                 .OrderBy(c => c)
                 .ToArray();
         }

         var modelPath = GetModelPath();
         mlContext.Model.Save(model, data.Schema, modelPath);
         _logger.LogInformation("Model saved to {ModelPath}", modelPath);

         return new TrainingMetricsResponse
         {
             MacroAccuracy = metrics.MacroAccuracy,
             MicroAccuracy = metrics.MicroAccuracy,
             LogLoss = metrics.LogLoss,
             LogLossReduction = metrics.LogLossReduction
         };
     }

     public TicketClassificationResponse Predict(TicketRequest request)
     {
         var ticketData = new TicketData
         {
             Subject = request.Subject,
             Description = request.Description,
             Priority = request.Priority
