 public class TicketModelService : ITicketModelService
 {
     private readonly ILogger<TicketModelService> _logger;
     private readonly IWebHostEnvironment _env;
     private readonly PredictionEnginePool<TicketData, TicketPrediction> _predictionEnginePool;
     private string[] _categoryNames = [];

     public TicketModelService(
         ILogger<TicketModelService> logger,
         IWebHostEnvironment env,
